# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BEŞ VAKİT NAMAZIN REKÂTLARI VE KILINIŞ ADIMLARI (TDB.1.2)</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Günlük Namaz Rekât Tablosu (Toplam 40)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Sabah (4): 2 Sünnet + 2 Farz</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Öğle (10): 4 İlk Sünnet + 4 Farz + 2 Son Sünnet</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• İkindi (8): 4 Sünnet + 4 Farz</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Akşam (5): 3 Farz + 2 Sünnet (Önce farz!)</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Yatsı (13): 4 İlk S. + 4 Farz + 2 Son S. + 3 Vitir</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Farzlar toplamı: 17 · Sünnet: 20 · Vitir (Vacip): 3</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İki Rekâtlı Namazın Kılınış Sırası</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">1. Niyet + İftitah Tekbiri («Allâhü Ekber»)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">2. 1. Rekât: Sübhaneke + Eûzü-Besmele + Fatiha +</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11.5" fill="#14532d">   Zamm-ı Sure → Rükû → İki Secde</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11.5" fill="#14532d">3. 2. Rekât: Besmele + Fatiha + Zamm-ı Sure →</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11.5" fill="#14532d">   Rükû → İki Secde → Son Oturuş (Ka\'de-i Âhire)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">4. Tahiyyat + Salli-Barik + Rabbena → Selam</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RÜKÛ VE SECDE TESBİHLERİ İLE CEMAATLE NAMAZ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Rükû ve Secde Tesbihleri</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">• Rükûda (3 kez):</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#78350f">  «Sübhâne Rabbiye\'l-Azîm» (Büyük Rabbim noksandan uzaktır)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#78350f">• Doğrulurken: «Semiallâhü limen hamideh» / «Rabbenâ...»</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">• Secdede (3 kez):</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11.5" fill="#78350f">  «Sübhâne Rabbiye\'l-A\'lâ» (Yüce Rabbim noksandan uzaktır)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Selam: «Esselâmü aleyküm ve rahmetullâh»</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Cemaatle Namaz, Ezan ve Kamet</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#831843">• İmam: Namazı önde kıldıran kişi</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11.5" fill="#831843">• Cemaat: İmama uyarak saf tutan müminler</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" fill="#831843">• Müezzin: Ezan ve kamet okuyan görevli</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11.5" fill="#831843">• Kamet: Farz namazlardan önce okunan,</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11.5" fill="#831843">  «Kad kâmeti\'s-salâh» ilaveli çağrı</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Cemaatle namaz bireysel namazdan 27 derece faziletlidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE DEĞERLENDİRMESİ: İSLAM VE İBADET GENEL ÖZETİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">İbadet ve Mükellefiyet</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">• Mükellef: Akıllı ve ergenlik</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#155e75">çağına ulaşmış Müslüman</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11.5" fill="#155e75">• Ef\'âl-i Mükellefîn: Farz, Vacip,</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" fill="#155e75">Sünnet, Mübah, Mekruh, Haram</text>\n  <text x="125" y="190" text-anchor="middle" font-size="11.5" fill="#155e75">• İhlas: İbadeti yalnız Allah</text>\n  <text x="125" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">rızası için samimiyetle yapmak</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">İbadetlerde Temizlik</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Abdestin Farzları (4): Yüz, kollar,</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#4c1d95">başın dörtte biri meshi, ayaklar</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Guslün Farzları (3): Ağız, burun,</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#4c1d95">tüm bedeni kuru yer kalmadan yıkama</text>\n  <text x="350" y="190" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Teyemmümün Farzları (2): Niyet</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#5b21b6">ve temiz toprakla yüz + kolları mesh</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Namazı Bozan Durumlar</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Namaz içinde konuşmak / gülmek</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">• Bir şey yemek veya içmek</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11.5" fill="#14532d">• Göğsünü kıbleden çevirmek</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11.5" fill="#14532d">• Abdestin bozulması</text>\n  <text x="575" y="188" text-anchor="middle" font-size="11.5" fill="#14532d">• Yanılma (unutma) durumunda</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Sehiv (Yanılma) Secdesi yapılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
